  const notifQRef=useRef([]);const notifBusyRef=useRef(false);const notifWkRef=useRef(0);
  const[notifPending,setNotifPending]=useState(false);/* [7.286.0 direttiva PO] la cascata di fine stagione TRATTIENE il pulsante della stagione nuova */
  useEffect(()=>{notifWkRef.current=(player.season||1)*100+(player.week||1);},[player.season,player.week]);
  const _drainNotif=()=>{if(notifBusyRef.current)return;
    let nx=notifQRef.current.shift();
    while(nx&&!nx.prio&&nx.wk&&nx.wk<notifWkRef.current)nx=notifQRef.current.shift();/* stantio: la settimana e' cambiata */
    if(!nx){setNotifPending(false);return;}
    const _q=notifQRef.current.length,_dur=_q>=4?1500:_q>=2?2100:_q>=1?2800:3600;
    notifBusyRef.current=true;setNotif(nx);try{AudioMgr.notifyCue(nx.msg,nx.color);}catch(_a){}
    setNotifPending(true);
    setTimeout(()=>{setNotif(null);setTimeout(()=>{notifBusyRef.current=false;if(!notifQRef.current.length)setNotifPending(false);_drainNotif();},260);},_dur);};
  const notify=(msg,color=TH.primary,opts)=>{
    const _e={msg,color,prio:!!(opts&&opts.prio),wk:notifWkRef.current};
    if(_e.prio)notifQRef.current.unshift(_e);else notifQRef.current.push(_e);
    /* il cap toglie i piu' VECCHI fra i MINORI: uno splice cieco in testa mangerebbe proprio i prioritari */
    while(notifQRef.current.length>8){const i=notifQRef.current.findIndex(x=>!x.prio);if(i<0)break;notifQRef.current.splice(i,1);}
    /* drenaggio DIFFERITO di un tick: una settimana accoda i suoi toast tutti nello stesso giro sincrono, e
       partendo subito il primo vedrebbe la coda vuota e si prenderebbe i 3.6s pieni (misurato) — cosi' invece
       la durata del PRIMO toast conosce gia' l'arretrato, e il prioritario e' davvero il primo a uscire. */
    setTimeout(_drainNotif,0);};

  // Sprint 19 — OVR milestone check (separate useEffect to avoid computing OVR outside setPlayer)
  useEffect(()=>{
    if(!player.ovr||!player.milestones)return;
    const ovrMs=CAREER_MILESTONES.filter(m=>m.id.startsWith("ovr")&&!player.milestones.includes(m.id)&&m.check(player));
    if(ovrMs.length===0)return;
    setPlayer(p=>({...p,milestones:[...(p.milestones||[]),...ovrMs.map(m=>m.id)]}));
    ovrMs.forEach((m,i)=>setTimeout(()=>{if(m.big)setMilestoneModal(m);else notify(m.txt,m.color);},400+i*2200));/* [7.147.0] via la coda (il setNotif diretto si clobberava coi toast del rollover) */
  },[player.ovr]);// eslint-disable-line

  // Sprint 15 — apply chosen interview answer to player state
  const applyInterviewAnswer=(ans)=>{
    const ef=ans.ef||{};
    const toneLabel=IV_TONE_LBL[ans.tone]||ans.tone;/* [7.8.11] stessa mappa del bottone (era divergente) */
    // Sprint 24C: polemic risk — compute from current state before setPlayer
    const jId=interviewModal?.journalistId;
    const curJ=jId?(player.journalists||[]).find(j=>j.id===jId):null;
    const isPolemic=ans.tone==="diretto"&&curJ?.type==="critico"&&(curJ?.trust||50)<45&&Math.random()<0.15;
    setPlayer(p=>{
      // Update journalist trust
      let updJournalists=p.journalists||[];
      if(jId){
        updJournalists=updJournalists.map(j=>{
          if(j.id!==jId)return j;
          let delta=0;
          if(ans.tone==="umile")delta=j.type==="fan"?8:j.type==="critico"?5:4;
          else if(ans.tone==="diplomatico")delta=j.type==="fan"?4:j.type==="critico"?2:3;
          else if(ans.tone==="diretto")delta=j.type==="fan"?-3:j.type==="critico"?-6:j.type==="investigativa"?2:-4;
          return{...j,trust:clamp((j.trust||50)+delta,0,100),lastTone:ans.tone};
        });
      }
      // Sprint 120: teamChemistry delta by tone
      const _tcDelta=ans.tone==="umile"?4:ans.tone==="diplomatico"?2:-3;
      return{
        ...p,
        journalists:updJournalists,
        morale:clamp((p.morale||70)+(ef.m||0),0,100),
        popularity:clamp((p.popularity||20)+popGain(p,ef.p||0)+(isPolemic?-8:0),0,100),
        coachTrust:clamp((p.coachTrust||60)+(ef.t||0)+(isPolemic?-5:0),0,100),
        form:clamp((p.form||70)+(ef.f||0),30,95),
        value:Math.max(0.5,(p.value||0.8)+(ef.v||0)),
        teamChemistry:clamp((p.teamChemistry||60)+_tcDelta,0,100),
        log:[`🎙️ [${ans.tone}] "${ans.txt.substring(0,45)}…"`,...(p.log||[])].slice(0,60),
      };
    });
    setInterviewFeedback({tone:ans.tone,label:toneLabel,ef});
    const wasPrematch=interviewModal?.matchCtx==="prematch";
    setInterviewModal(null);
    setTimeout(()=>setInterviewFeedback(null),2800);
    if(isPolemic)setTimeout(()=>notify(`🔥 POLEMICA! ${curJ?.name||"Il giornalista"} risponde duramente. Il caso esplode sui social.`,"#ef4444"),600);
    // Sprint D3: after closing the pre-match press conference, fire the deferred mister talk
    if(wasPrematch){
      const _disc=pendingMisterDiscorsoRef.current;
      pendingMisterDiscorsoRef.current=null;
      if(_disc)setTimeout(()=>setMisterDiscorsoModal(_disc),350);
    }
  };

  // global keyboard shortcuts
  useEffect(()=>{
    const onKey=e=>{
      if(_scrive386(e))return;/* [7.386.0] chi scrive tiene la tastiera */
      if(e.target.tagName==="INPUT"||e.target.tagName==="SELECT"||e.target.tagName==="TEXTAREA")return;
      const inModal=weekLiveModal||showAdvanceConfirm||showMatchPrompt||transferOffer;
      // ESC — close modals / go back
      if(e.key==="Escape"){
        e.preventDefault();
        if(screen==="match"){if(!matchContext||matchContext==="career"){setScreen("dashboard");setTab("dashboard");}}/* [6.80.0] ESC non abbandona MAI nazionale/coppe (stesso principio del back link) */
        else if(screen==="postmatch"){setScreen("dashboard");setTab("dashboard");}
        else if(screen==="press"){setScreen("dashboard");setTab("dashboard");}
        else if(weekLiveModal){setWeekLiveModal(null);}
        else if(showMatchPrompt){setShowMatchPrompt(null);}
        else if(showAdvanceConfirm){setShowAdvanceConfirm(false);}
        else if(transferOffer){setTransferOffer(null);}
        return;
      }
      // Space / Enter — confirm top action
      if(e.key===" "||e.code==="Space"){
        e.preventDefault();
        if(weekLiveModal){setWeekLiveModal(null);}
        else if(showMatchPrompt){setShowMatchPrompt(null);startMatch();}
        else if(showAdvanceConfirm){doAdvanceWeek();}
        else if(screen==="postmatch"){setScreen("dashboard");setTab("dashboard");}
        else if(screen==="press"){setScreen("dashboard");setTab("dashboard");}
        return;
      }
      if(e.key==="Enter"){
        e.preventDefault();
        // Modals take priority
        if(weekLiveModal){setWeekLiveModal(null);return;}
        if(showMatchPrompt){setShowMatchPrompt(null);startMatch();return;}
        if(showAdvanceConfirm){doAdvanceWeek();return;}
        if(transferOffer){acceptTransfer();return;}
        // Screens
        if(screen==="postmatch"){setScreen("dashboard");setTab("dashboard");return;}
        if(screen==="press"){setScreen("dashboard");setTab("dashboard");return;}
        if(screen==="dashboard"){handleContinua();return;}
        return;
      }
      // Number shortcuts — 0 = advance week (with match check)
      if((e.key==="0"||e.code==="Numpad0")&&screen==="dashboard"&&!inModal){
        e.preventDefault();
        const md0=getThisWeekMatchday();
        if(md0&&player.weekLived){setShowMatchPrompt(md0);}else{setShowAdvanceConfirm(true);}
        return;
      }
      // Only process letter shortcuts when no modal and not in match
      if(_scrive386(e))return;/* [7.386.0] e nemmeno quando l'utente sta scrivendo: qui le scorciatoie sono LETTERE (P, A, S, N, M, H), quindi scrivere «senza» in un campo di testo cambiava scheda a meta' parola */
      if(inModal||screen==="match")return;
      const k=e.key.toUpperCase();
      // Tab shortcuts: 1-5 or letters
      if(k==="P"&&screen==="dashboard"){e.preventDefault();if(getThisWeekMatchday())startMatch();}
      else if(k==="A"&&screen==="dashboard"){e.preventDefault();const mdA=getThisWeekMatchday();if(mdA&&player.weekLived){setShowMatchPrompt(mdA);}else{setShowAdvanceConfirm(true);}}
      else if(k==="S"){e.preventDefault();doSave();}
      else if(k==="F"){e.preventDefault();goTab("standings");}
      else if(k==="C"){e.preventDefault();goTab("calendar");}
      else if(k==="R"){e.preventDefault();goTab("profile");}
      else if(k==="G"){e.preventDefault();goTab("agente");}
      else if(k==="S"){e.preventDefault();goTab("club");}
      else if(k==="N"){e.preventDefault();goTab("nazionale");}
      else if(k==="M"||k==="H"){e.preventDefault();goTab("dashboard");}
      // Arrow keys for tab switching
      else if(e.key==="ArrowLeft"&&!inModal){
        e.preventDefault();
        const tabs=["dashboard","stagione","club","carriera","agente"];
        const cur=tabs.indexOf(_tabToContainer(tab));if(cur>0)goTab(tabs[cur-1]);
      }else if(e.key==="ArrowRight"&&!inModal){
        e.preventDefault();
        const tabs=["dashboard","stagione","club","carriera","agente"];
        const cur=tabs.indexOf(_tabToContainer(tab));if(cur<tabs.length-1)goTab(tabs[cur+1]);
      }
    };
    window.addEventListener("keydown",onKey);
    return()=>window.removeEventListener("keydown",onKey);
  },[screen,weekLiveModal,showAdvanceConfirm,showMatchPrompt,transferOffer,tab,matchContext]);// eslint-disable-line [6.80.0] matchContext nel closure (guardia ESC nazionale)

  // Autosave — debounced 600ms to avoid redundant writes during rapid state updates
  const saveTimerRef=useRef(null);
  /* [9ª ricorrenza «partita gia' giocata» — G34 vs Bilbao col titolo, build 7.443 con tutte le reti]
     IL SIDECAR DEL FISCHIO FINALE SI CONSUMA QUI, A COMMIT PERSISTITO. Il sidecar e' l'unica prova della
     partita giocata; consumarlo al commit in MEMORIA (7.24.3) o al dispatch del recovery (7.178) lasciava
     la finestra commit→autosave: un kill di Android li' dentro (pagehide non sempre arriva, nota 5.75)
     riportava il save a PRIMA della partita con la prova gia' distrutta → big match riproposto, save
     finale senza cicatrici. Ora: il sidecar muore solo quando lo stato APPENA SALVATO mostra la gara
     committata (nessuna voce di calendario non giocata compatibile). Finche' vive, la rete (G) del
     selettore tiene la gara fuori dalla riproposta e il recovery al mount la ricommitta. */
  const _mrCleanup=(pSaved)=>{try{
    const _raw=localStorage.getItem('cpm-pending-mr');if(!_raw)return;
    const _pk=JSON.parse(_raw);if(!_pk||_pk.v!==1)return;
    if(_pk.n!==((pSaved&&pSaved.name)||"")||_pk.s!==((pSaved&&pSaved.season)||1))return;/* di un altro save/stagione: ci pensa la validazione al mount */
    const _r=_pk.result||{};
    /* [7.451.0 · FASE 8] il confronto e' per avversario E COMPETIZIONE: cercando per solo avversario, una
       gara di CAMPIONATO ancora da giocare contro lo stesso club teneva in vita all'infinito il sidecar di
       una COPPA gia' committata — e finche' quel sidecar vive la rete (G) sotto tiene fuori dalla riproposta
       la gara di campionato legittima. Stessa radice del P0, stessa regola condivisa. */
    const _ctx451=(typeof window!=="undefined"&&window.__CPM_NO_P0_5)?null:(_r.context||null);
    const _ih452=(typeof window!=="undefined"&&window.__CPM_NO_P0_6)?null:_pk.ih;/* [CAL-03] la SEDE completa l'identita' */
    const _open=((pSaved&&pSaved.calendar)||[]).some(m=>m&&!m.played&&_mdMatchesCtx(_ctx451,m)&&_mdSameVenue(_ih452,m)&&(
      (_pk.oid&&m.opponentId===_pk.oid)||(_pk.on&&m.opponentName===_pk.on)
      ||(m.opponentName&&m.opponentName===_r.opponent)||(m.opponentId&&m.opponentId===_r.opponent)));
    if(!_open)localStorage.removeItem('cpm-pending-mr');/* la gara e' nel salvataggio: prova non piu' necessaria */
  }catch(_e){}};
  useEffect(()=>{
    if(saveTimerRef.current)clearTimeout(saveTimerRef.current);
    saveTimerRef.current=setTimeout(()=>{
      storage.save({phase:"career",player},currentSlot).then(ok=>{if(ok){setLastSaved(Date.now());_mrCleanup(player);}else notify("⚠️ Salvataggio fallito — spazio insufficiente sul dispositivo.",TH.danger);});
    },600);
    return()=>{if(saveTimerRef.current)clearTimeout(saveTimerRef.current);};
  },[player]);// eslint-disable-line

  /* [7.462.0 richiesta PO «dopo il galà almeno salva la partita»] IL GALA' E' UN PUNTO DI SALVATAGGIO.
     L'autosave e' a debounce di 600ms sul cambio di `player` (sopra), e la schermata premi arriva subito
     dopo il commit di fine stagione: nella normalita' quel salvataggio parte. Ma `screen` NON e' persistito
     e la cerimonia e' il momento in cui si posa il telefono — chi chiude li' riapre al cruscotto, e il
     dubbio «ho perso la stagione?» se lo porta dietro. Qui il salvataggio e' IMMEDIATO (scavalca il
     debounce) e DICHIARATO: la conferma e' l'unica cosa che distingue un salvataggio silenzioso da un
     salvataggio mancato, ed e' esattamente cio' che il PO non vedeva. */
  useEffect(()=>{
    if(screen!=="seasonAwards")return;
    try{
      if(saveTimerRef.current)clearTimeout(saveTimerRef.current);
      storage.save({phase:"career",player},currentSlot).then(ok=>{
        if(ok){setLastSaved(Date.now());_mrCleanup(player);notify("💾 Stagione salvata.",TH.success);}
        else notify("⚠️ Salvataggio fallito — spazio insufficiente sul dispositivo.",TH.danger);
      }).catch(()=>{});
    }catch(_e){}
  },[screen]);// eslint-disable-line

  // [5.75.0 F0-6] flush IMMEDIATO del save quando l'app va in background (pagehide/visibilitychange):
  //   col solo debounce 600ms lo swipe-away su mobile perdeva l'ultimo update (su Android WebView pagehide è spesso l'unica finestra utile).
  const _flushRef=useRef(null);
  useEffect(()=>{_flushRef.current={player,slot:currentSlot};},[player,currentSlot]);// eslint-disable-line
  useEffect(()=>{
    const flush=()=>{try{const f=_flushRef.current;if(f&&f.player){if(saveTimerRef.current)clearTimeout(saveTimerRef.current);storage.save({phase:"career",player:f.player},f.slot).then(ok=>{if(ok)_mrCleanup(f.player);}).catch(()=>{});}}catch(_e){}};/* [9ª ricorrenza] anche il flush di pagehide consuma il sidecar SOLO a salvataggio riuscito */
    const onVis=()=>{if(document.visibilityState==="hidden")flush();};
    window.addEventListener("pagehide",flush);
    document.addEventListener("visibilitychange",onVis);
    return()=>{window.removeEventListener("pagehide",flush);document.removeEventListener("visibilitychange",onVis);};
  },[]);// eslint-disable-line

  // Manual save
  const doSave=useCallback(async()=>{
    const ok=await storage.save({phase:"career",player},currentSlot);
    if(ok){setLastSaved(Date.now());notify("💾 Carriera salvata!",TH.success);if(onRefreshSlots)onRefreshSlots();}
    else notify("⚠️ Errore nel salvataggio.",TH.danger);
  },[player,currentSlot,onRefreshSlots]);// eslint-disable-line

  // Export to JSON
  const exportSave=()=>{
    const data={phase:"career",player,savedAt:Date.now(),saveVersion:SAVE_VERSION};
    const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"});
    const url=URL.createObjectURL(blob);
    const a=document.createElement("a");a.href=url;
    a.download=`cpm-${player.name.replace(/\s/g,"-")}-S${player.season||1}.json`;
    a.click();URL.revokeObjectURL(url);
    notify("📁 File esportato!",TH.success);
  };

  const _containerDefault={stagione:"standings",carriera:"profile"};/* [7.67.0 collaudo PO «appena clicco sul Tab sono più interessato alla classifica»] Stagione apre sulla CLASSIFICA */
  const _tabToContainer=t=>["calendar","standings","coppe"].includes(t)?"stagione":["profile","nazionale"].includes(t)?"carriera":t;
  const goTab=t=>{const r=_containerDefault[t]||t;setTab(r);setScreen(r);try{safeLS.set("cpm-active-tab",r);}catch(_e){}};/* [7.149.0] persiste il tab per l'auto-ripresa (stesso punto dopo background) */
  // Sprint A: early return from injury
  // §9.6: relapse_risk graduato — più settimane mancano e più la gravità è alta, più rischi la ricaduta
  const injuryRelapseRisk=(p)=>{
    const wkRem=Math.max(0,p.injuryWeeks||0);
    const orig=Math.max(1,p.originalInjuryWeeks||p.injuryWeeks||1);
    const sevW={lieve:0.10,medio:0.18,grave:0.28}[p.injurySeverity||"medio"]||0.18;
    // §9.6 × 9.3: un buon preparatore (fitnessCoachRel) gestisce la riabilitazione → riduce il rischio ricaduta (fino a -0.125)
    const fitProt=clamp(((p.fitnessCoachRel||50)-50)/400,0,0.125);
    return clamp(sevW+0.45*(wkRem/orig)-fitProt,0.05,0.85);
  };
  const handleForceReturn=()=>{
    const relapse=Math.random()<injuryRelapseRisk(player);
    if(relapse){
      const nWk=Math.max(2,player.originalInjuryWeeks||player.injuryWeeks||2);
      setPlayer(p=>({...p,injured:true,injuryWeeks:nWk,originalInjuryWeeks:nWk,injurySeverity:"medio",returnPenaltyWeeks:0,justRecovered:false}));
      notify("😱 Ricaduta! Il muscolo non era pronto. Stop prolungato.",TH.danger);
    }else{
      setPlayer(p=>({...p,injured:false,injuryWeeks:0,justRecovered:true,returnPenaltyWeeks:clamp(1+Math.ceil((p.injuryWeeks||1)*0.8),2,5)}));/* [7.9.0 direttiva PO «malus proporzionale»] il malus scala con le settimane di recupero SALTATE (non con la durata originale: su uno stop da 12 settimane dava 12 settimane di rientro graduale = peggio che scontare lo stop), cap 5 */
      notify("✅ Rientro anticipato riuscito. Sei ancora fragile — attenzione.",TH.warning);
    }
    setForceReturnConfirm(false);
  };
  // only allow playing if current week has a scheduled match
    /* [7.312.0 collaudo PO «un'altra volta stesso bug. correggi definitivamente. le partite possono essere
     simulate, giocate NON deve piu' ricapitare. E' grave» — 7ª ricorrenza della classe]
     IL REGISTRO DELLE GIORNATE GIOCATE ORA SOPRAVVIVE AL RELOAD.
     Tutte le guardie accumulate finora (6.91 · 6.98 · 7.0.5 · 7.5.2 · 7.210 · 7.302) hanno una cosa in
     comune: DEDUCONO che una gara e' stata giocata da un altro campo — la voce di calendario marcata, il
     nome dell'avversario nello storico, la sede, la settimana, il conteggio in classifica. Basta che UNO di
     quei campi non venga scritto (un errore a meta' commit, un'app chiusa, una marcatura che non combacia
     per nome) perche' l'intera catena sia cieca. L'unica rete che non deduceva niente — `_committedMdRef`,
     6.73 — era un `useRef`: viveva in memoria e MORIVA a ogni riavvio dell'app, cioe' esattamente nel caso
     in cui serviva.
     Ora la stessa informazione e' un campo del salvataggio: `player.playedMd = {s:<stagione>, md:[numeri]}`.
     Si scrive nello STESSO setPlayer che committa il risultato (atomico col save, live e simulato), si legge
     come guardia (F), si azzera al rollover di stagione. Non dipende da nessun'altra chiave: una giornata
     committata non puo' piu' essere riproposta, comunque sia andato il resto del commit.
     Campo lazy → nessun bump di SAVE_VERSION. */
  const _mdCommit=(p,mdNum)=>{
    if(!p||mdNum==null)return p;
    const sn=p.season||1,cur=(p.playedMd&&p.playedMd.s===sn&&Array.isArray(p.playedMd.md))?p.playedMd.md:[];
    if(cur.indexOf(mdNum)>=0)return (p.playedMd&&p.playedMd.s===sn)?p:{...p,playedMd:{s:sn,md:cur}};
    return {...p,playedMd:{s:sn,md:[...cur,mdNum]}};
  };
/* [7.418.0 collaudo PO «di nuovo il bug della partita gia' giocata! risolvi definitivamente, e' grave»
   — 8ª ricorrenza della classe] IL RILEVATORE E' UNO SOLO E LO USANO TUTTI. Le sette reti (A→G)
   vivevano DENTRO getThisWeekMatchday — cioe' proteggevano SOLO il path del gioco dal vivo. Ma
   simulateAndAdvance pescava dal calendario GREZZO (`find(week && !played)`) e doAdvanceWeek pure
   (`filter(week && !played)`): una gemella stantia che il vivo rifiutava veniva RISIMULATA da
   «Avanza»/«Simula», ricontata in classifica e storico — ed e' proprio cosi' che lo stato torna
   incoerente e il bug riaffiora a ogni lotto. Il rilevatore ora e' una funzione PURA (p, md) usata
   da tutti e tre i selettori, con una rete NUOVA: (H) LA CLASSIFICA — la giornata N di lega si
   gioca con N-1 gare in tabella; se la mia riga dice played ≥ N, la giornata N e' GIA' dentro la
   classifica e la voce e' stantia, qualunque campo un desync abbia sporcato. In piu': BONIFICA
   AUTOMATICA VISIBILE (effect sotto) — le voci stantie scadute vengono marcate e la bonifica lascia
   una riga nel log, cosi' il PO VEDE la rete che lavora invece di un silenzio. */
/* [7.451.0 · messa in sicurezza FASE 8] UNA SOLA REGOLA DI COMPETIZIONE, CONDIVISA.
   Il P0 della «partita gia' giocata» ha una radice sola: cercare la gara nel calendario per SOLO
   avversario. Il Madrid lo si incontra in campionato, in coppa e in Europa: senza filtrare per
   competizione, il risultato di una gara finisce sulla voce sbagliata. Il fix del 7.447.0 l'ha chiusa nel
   recovery, ma l'audit post-fix ha trovato la stessa ricerca cieca in altri due punti (_mrCleanup e la
   rete (G) del selettore). Invece di ripetere la condizione tre volte — che e' esattamente il modo in cui
   una rete si sfilaccia al lotto successivo — la regola vive QUI, in un posto solo.
   `ctx` e' il `context` del risultato scritto nel sidecar al fischio finale; ignoto ⇒ nessun filtro (come
   prima), perche' un sidecar scritto da una versione precedente non deve smettere di funzionare. */
const _mdMatchesCtx=(ctx,md)=>{
  if(!md)return false;
  const _t=(ctx==="cup")?"cup":(ctx==="euro_group")?"euro_group":(ctx==="euro_ko")?"euro":(ctx==="career")?"__lega__":null;
  if(!_t)return true;/* contesto ignoto: nessun filtro */
  if(_t==="__lega__")return !md.type||(md.type!=="cup"&&md.type!=="euro_group"&&md.type!=="euro"&&md.type!=="national");
  return md.type===_t;
};
