        const _evoCl=(player.clubEvo&&player.clubEvo.clubId===(club.id||club.n))?player.clubEvo:null;const capP=(typeof stadiumConfigFor==="function")?stadiumConfigFor(club,{prestigeShift:(player.clubPrestigeShifts||{})[club.id||club.n]||0,stadiumTier:_evoCl?_evoCl.stadiumTier:0}).capacity:(prestige>=90?62000:prestige>=80?36000:prestige>=65?17500:prestige>=52?8000:prestige>=38?9000:900);
        const capStr=capP>=1000?(capP/1000).toFixed(0)+"k":capP+"";
